// SECDED (39,32): 32 data bits + 6 Hamming check bits + 1 overall parity bit
package secded32_pkg;
  // Each Hamming check bit is the parity of the data bits selected by a mask
  // (data bit i sits at Hamming position 3, 5, 6, 7, 9, ... - never a power of 2)
  localparam logic [31:0] M0 = 32'h56AA_AD5B, M1 = 32'h9B33_366D,
                          M2 = 32'hE3C3_C78E, M3 = 32'h03FC_07F0,
                          M4 = 32'h03FF_F800, M5 = 32'hFC00_0000;

  function automatic logic [5:0] hamming(input logic [31:0] d);
    return {^(d & M5), ^(d & M4), ^(d & M3), ^(d & M2), ^(d & M1), ^(d & M0)};
  endfunction

  // syndrome (error position) -> data bit index; 63 = not a data bit
  localparam logic [5:0] DATA_BIT [64] = '{
    6'd63, 6'd63, 6'd63, 6'd0, 6'd63, 6'd1, 6'd2, 6'd3,
    6'd63, 6'd4, 6'd5, 6'd6, 6'd7, 6'd8, 6'd9, 6'd10,
    6'd63, 6'd11, 6'd12, 6'd13, 6'd14, 6'd15, 6'd16, 6'd17,
    6'd18, 6'd19, 6'd20, 6'd21, 6'd22, 6'd23, 6'd24, 6'd25,
    6'd63, 6'd26, 6'd27, 6'd28, 6'd29, 6'd30, 6'd31, 6'd63,
    6'd63, 6'd63, 6'd63, 6'd63, 6'd63, 6'd63, 6'd63, 6'd63,
    6'd63, 6'd63, 6'd63, 6'd63, 6'd63, 6'd63, 6'd63, 6'd63,
    6'd63, 6'd63, 6'd63, 6'd63, 6'd63, 6'd63, 6'd63, 6'd63
  };
endpackage

module secded32_enc
  import secded32_pkg::*;
(
  input  logic [31:0] data,
  output logic [6:0]  check            // {overall parity, 6 Hamming bits}
);
  logic [5:0] h;
  assign h     = hamming(data);
  assign check = {^{data, h}, h};       // overall parity over all 38 bits
endmodule

module secded32_dec
  import secded32_pkg::*;
(
  input  logic [31:0] data_in,
  input  logic [6:0]  check_in,
  output logic [31:0] data_out,          // corrected data
  output logic        ce,                // a single error was corrected
  output logic        ue                 // uncorrectable (double) error
);
  logic [5:0] syn;                       // syndrome: position of a single error
  logic       par;                       // 1 = odd number of flipped bits
  logic [5:0] bad_bit;                   // data bit at that position

  assign syn      = check_in[5:0] ^ hamming(data_in);
  assign par      = ^{data_in, check_in};
  assign bad_bit  = DATA_BIT[syn];
  assign data_out = (par && bad_bit != 6'd63) ? data_in ^ (32'd1 << bad_bit)
                                              : data_in;
  assign ce = par;                       // error in data, check or parity bit
  assign ue = !par && (syn != '0);       // two errors: detected only
endmodule

module ecc_ram #(
  parameter  int DEPTH = 1024,
  localparam int AW    = $clog2(DEPTH)
) (
  input  logic          clk, en, we,
  input  logic [AW-1:0] addr,
  input  logic [31:0]   din,
  output logic [31:0]   dout,            // corrected read data
  output logic          ce, ue           // error flags of this read
);
  logic [6:0]  check_w;
  logic [38:0] code_r;                   // stored word: {check bits, data}

  secded32_enc u_enc (.data(din), .check(check_w));

  sp_ram #(.DW(39), .DEPTH(DEPTH)) u_ram (
    .clk, .en, .we, .addr,
    .din ({check_w, din}),
    .dout(code_r));

  secded32_dec u_dec (
    .data_in (code_r[31:0]),
    .check_in(code_r[38:32]),
    .data_out(dout), .ce, .ue);
endmodule
